public static MwmsProcessMoveInventory Construct()
{
    return new MwmsProcessMoveInventory();
}

protected void new()
{
    processName = 'MoveInventory';
    MwmsLogicBlockMoveLicensePlate              LPBlock   = MwmsLogicBlockMoveLicensePlate::Construct();
    MwmsLogicBlockMoveInvent                    itemBlock = new MwmsLogicBlockMoveInvent();
    super();
    MwmsProcessCreateTransferJournalLine::addBlocksForHandlingLicenseAndItems(this, itemBlock, LPBlock);
}
